INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Voluntary B2B (Peppol/ebInterface) — mandatory B2G since 2014', 'This deep-dive page reflects publicly available guidance and reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Austria''s formal domestic B2B e-invoicing proposal was expected in Q3 2026 but had not been published at time of writing — confirm current status directly with the BMF or RIS before building against it.', 'Austria was one of the earliest EU countries to mandate B2G e-invoicing, with a federal requirement in force since 1 January 2014 — years before most of its peers. B2B remains voluntary today, but that''s under active review: the Finance Ministry has signalled a Peppol-based domestic mandate is coming, with a formal proposal expected in the third quarter of 2026, against a firm EU-law floor of July 2030 for cross-border B2B regardless of the outcome.', 'Austria is unusual in accepting two genuinely distinct formats for the same B2G obligation: ebInterface, its own long-running national XML standard, and Peppol BIS 3.0. Both are EN 16931-aligned since ebInterface 5.0, so a business capable of either is positioned for whatever a future domestic B2B mandate brings.', 'B2G submission runs through the USP (Unternehmensserviceportal) — either a direct web upload in ebInterface format, or via the Peppol network — with a legacy EDIAKT II channel still available for large suppliers with pre-existing EDI connections. There is no domestic clearance or real-time reporting model for B2B, which remains a matter of bilateral agreement between trading partners.', 'With B2B still voluntary, most businesses'' near-term work is about readiness rather than compliance: confirming ebInterface or Peppol capability, watching for the BMF''s domestic scope decision, and preparing for the confirmed 2030 EU cross-border floor regardless of what that decision covers.', 'There is no domestic B2B penalty regime today because there is no domestic B2B mandate — the closest thing to enforcement is B2G invoice rejection for non-compliant format, plus the approaching EU-law floor that applies regardless of Austria''s own timeline.', 'Austria has run mandatory B2G e-invoicing since 1 January 2014 (IKTKonG §5) — one of the earliest such mandates in the EU — extended in 2018 to cover all central contracting authorities (BVergG 2018 §368), with several of its nine Länder adopting comparable requirements of their own. B2B remains voluntary. The Finance Ministry has indicated it will pursue a Peppol-based domestic B2B mandate, mirroring Belgium and the Netherlands, with a formal proposal expected in Q3 2026 — not yet published as of early August 2026. Separately, ViDA''s cross-border B2B e-invoicing and reporting mandate is confirmed EU law from 1 July 2030, regardless of the domestic outcome.', '🇦🇹' FROM countries WHERE name_en = 'Austria';
