INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Standards accepted", "ebInterface (6.0/6.1) or Peppol BIS Billing 3.0 — either is valid for B2G"], ["Legal basis", "IKTKonG §5, BGBl. I Nr. 35/2012 (2014); extended by BVergG 2018 §368"], ["EN 16931 alignment", "ebInterface 5.0 onward; version 7.0 (due Q4 2026) adds a formal syntax binding"], ["B2B today", "No mandated format — Peppol and ebInterface both used voluntarily"]]', 'Unlike most of this tracker, Austria doesn''t force a single national format — a business already capable of Peppol for other EU markets needs no additional format work for Austrian B2G, and the same applies in reverse for an ebInterface-only implementation.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["B2G registration", "Via the USP (Unternehmensserviceportal), using FinanzOnline credentials"], ["Standard governance", "ebInterface is maintained by AUSTRIAPRO, a working group of the WKO (Austrian Federal Economic Chamber)"], ["Peppol identity", "Peppol Participant ID via any Access Point provider"], ["B2B today", "No registration required — bilateral agreement between trading partners"]]', 'The USP registration step is specific to government suppliers — a business only trading B2B voluntarily today has no registry to join at all.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["B2G", "Full EN 16931 core invoice model, in either accepted format"], ["Legacy channel", "EDIAKT II remains available for large suppliers with pre-existing EDI connections, though new implementations should use ebInterface or Peppol"], ["Archiving", "7 years, standard Austrian record-keeping requirement"]]', 'Because both accepted formats are EN 16931-aligned, the underlying data requirements are identical regardless of which one a supplier chooses.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["B2G model", "Direct USP web upload, or the Peppol four-corner network"], ["B2B model", "Voluntary bilateral exchange, commonly over Peppol"], ["Real-time reporting", "None today — Austria has no domestic clearance or CTC regime"], ["SAF-T", "An on-demand system has existed since 2009; a reported 2024 ''relaunch'' toward periodic filing remains unconfirmed as of mid-2026"]]', 'As with the Netherlands, there''s no clearance model to describe here for B2B — invoices move directly between trading partners, a deliberate contrast to Belgium, France, Italy, and Poland.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Channels', '[["USP web upload", "Manual submission in ebInterface format via erechnung.gv.at"], ["Peppol network", "The recommended channel for cross-border-capable suppliers"], ["EDIAKT II", "Legacy EDI channel for large suppliers with pre-existing connections"], ["Scope", "All Bundesbehörden (federal agencies); several Länder, including Vienna, Lower Austria, and Upper Austria, have adopted their own comparable requirements"]]', 'Businesses should check whether the specific public body they invoice is a federal agency (covered nationally since 2014/2018) or falls under one of the Länder''s own, separately-adopted rules.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The pending domestic decision', '[["Current status", "B2B voluntary; no domestic mandate or real-time reporting regime"], ["BMF signal", "A Peppol-based domestic mandate, mirroring Belgium and the Netherlands"], ["Formal proposal", "Expected Q3 2026 — not yet published as of early August 2026"], ["Firm floor regardless", "1 July 2030 — ViDA cross-border B2B, confirmed EU law"]]', 'This is the one entry on this page that is genuinely undecided — track the sources page and the tracker board for the BMF''s formal proposal once published, since it will determine the scope and timeline of any domestic B2B requirement.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ B2G rejection', NULL, NULL, 'Non-compliant invoices to Austrian federal agencies face rejection under the USP''s format requirements — the closest thing to enforcement that exists today, and confined to government trade rather than the broader economy.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🤝 No domestic B2B penalty regime yet', NULL, NULL, 'There is no legal penalty for B2B non-compliance today, because there is no legal B2B requirement. In practice, businesses adopt Peppol or ebInterface voluntarily to stay interoperable with EU trading partners already under mandatory regimes elsewhere.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🇪🇺 The approaching EU floor', NULL, NULL, 'Regardless of what Austria decides domestically, ViDA''s cross-border requirement is confirmed EU law from 1 July 2030 — every Austrian business doing intra-EU B2B trade will need EN 16931-compliant e-invoicing and digital reporting for those transactions, mandate or no mandate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your ebInterface or Peppol capability', 'Check whether your ERP or accounting platform already supports ebInterface (6.0/6.1) or Peppol BIS 3.0 — many mainstream Austrian and EU platforms support at least one natively.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Verify your B2G channel if you supply Austrian public bodies', 'Confirm you''re registered via the USP and submitting correctly, and check whether the specific body you invoice is federal (covered since 2014/2018) or falls under a Land''s own separately-adopted requirement.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Track the BMF''s domestic B2B proposal', 'This is the single most consequential open question for Austrian e-invoicing — the formal proposal expected in Q3 2026 will determine the scope and timeline of any domestic B2B mandate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for the confirmed 2030 cross-border floor regardless', 'Even before any domestic mandate lands, every business doing intra-EU B2B trade needs EN 16931 e-invoicing and digital reporting capability from 1 July 2030 — this date is fixed by EU directive, not Austrian discretion.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Austria';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for ebInterface 7.0', 'Due in Q4 2026 with a formal EN 16931 syntax binding — no mandatory migration from 6.0/6.1 has been announced, but it''s worth knowing about if you use ebInterface directly rather than Peppol.');
